class Solution(object):
    def uncommonFromSentences(self, s1, s2):
        """
        :type s1: str
        :type s2: str
        :rtype: List[str]
        """
        s1 = collections.Counter(s1.split())
        s2 = collections.Counter(s2.split())
        ans = []
        for k, v in s1.items():
            if v == 1 and k not in s2:
                ans.append(k)
        for k, v in s2.items():
            if v == 1 and k not in s1:
                ans.append(k)
        return ans
